/* @lc app=leetcode id=3430 lang=kotlin */ class Solution { fun cnt(a: Int, b: Int, k: Int): Long = (k + 1).let { s -> minOf(a, s - 1).let { t -> maxOf(0, minOf(t, s - b)).let { p -> p.toLong() * b + (t - p).toLong() * s - (t.toLong() * (t + 1) / 2 - p.toLong() * (p + 1) / 2) } } } fun ms(a: IntArray, k: Int): Long = a.size.let { n -> IntArray(n) { -1 }.let { pl -> IntArray(n) { n }.let { nr -> java.util.ArrayDeque<Int>().let { st -> a.indices.forEach { i -> generateSequence { st.peekFirst()?.takeIf { a[it] < a[i] } }.forEach { _ -> st.pollFirst().let { nr[it] = i } }.let { pl[i] = st.peekFirst() ?: -1 }.let { st.addFirst(i) } }.let { a.indices.sumOf { i -> a[i].toLong() * cnt(i - pl[i], nr[i] - i, k) } } } } } } fun minMaxSubarraySum(nums: IntArray, k: Int): Long = ms(nums, k) - ms(IntArray(nums.size) { -nums[it] }, k) }